  const { data: keywords } = await sb.from("bank_import_keywords").select("*").eq("user_id", userId).eq("is_active", true).eq("is_ignore", false);
  const kw = (keywords ?? []).find((k) => description.toLowerCase().includes((k.keyword || "").toLowerCase()));
  let vendorId = null;
